function safe(rel){if(path.isAbsolute(rel)||rel.split(/[\\/]/).some(p=>p==='..'||p==='.git'))throw Error('Unsafe path');let p=root;for(const part of rel.split('/')){p=path.join(p,part);try{if(fs.lstatSync(p).isSymbolicLink())throw Error('Symlink refused: '+rel)}catch(e){if(e.code!=='ENOENT')throw e}}return p}
function read(rel){const p=safe(rel);if(!fs.existsSync(p))return null;if(!fs.statSync(p).isFile())throw Error('Expected file: '+rel);return fs.readFileSync(p)}
function write(rel,data){const p=safe(rel);if(data===null){if(fs.existsSync(p))fs.unlinkSync(p)}else{fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,data)}}
